import json

# Verify all chart data matches source_data.json
with open('/app/benchmark/source_data.json') as f:
    src = json.load(f)

# Check income data
income_src = {d['region']: [] for d in src['internet_by_income_quintile']['data']}
for d in src['internet_by_income_quintile']['data']:
    income_src[d['region']].append(d['penetration'])

income_chart = {
    'Sub-Saharan Africa': [6, 14, 25, 42, 68],
    'South Asia': [12, 24, 39, 56, 78],
    'Europe': [72, 82, 89, 94, 97],
    'North America': [75, 85, 92, 96, 99],
}

for r in income_src:
    assert income_src[r] == income_chart[r], f'Income mismatch for {r}: {income_src[r]} != {income_chart[r]}'

# Check age data
age_src = {d['region']: [] for d in src['internet_by_age_group']['data']}
for d in src['internet_by_age_group']['data']:
    age_src[d['region']].append(d['penetration'])

age_chart = {
    'Sub-Saharan Africa': [38, 32, 26, 18, 11, 5],
    'South Asia': [55, 48, 38, 27, 16, 8],
    'Europe': [98, 96, 93, 88, 79, 58],
    'North America': [99, 97, 95, 91, 84, 65],
}

for r in age_src:
    assert age_src[r] == age_chart[r], f'Age mismatch for {r}: {age_src[r]} != {age_chart[r]}'

# Check urban-rural data
ur_src = {}
for d in src['internet_by_urban_rural']['data']:
    ur_src.setdefault(d['region'], {})[d['setting']] = d['penetration']

ur_chart = {
    'Sub-Saharan Africa': (13, 42),
    'South Asia': (22, 58),
    'Europe': (78, 92),
    'North America': (80, 95),
}

for r in ur_src:
    assert ur_src[r]['Rural'] == ur_chart[r][0], f'Urban-rural mismatch for {r} Rural'
    assert ur_src[r]['Urban'] == ur_chart[r][1], f'Urban-rural mismatch for {r} Urban'

# Check overall data
ov_src = {d['region']: d['overall_penetration'] for d in src['internet_overall_by_region']['data']}
ov_chart = {'Sub-Saharan Africa': 27, 'South Asia': 40, 'Europe': 89, 'North America': 93}
for r in ov_src:
    assert ov_src[r] == ov_chart[r], f'Overall mismatch for {r}: {ov_src[r]} != {ov_chart[r]}'

print('All data validation checks passed. Chart data is fully traceable to source_data.json.')
"

